im=Image.open('/home/robot/captures/top_001.png').convert('RGB')
w,h=im.size
print('size',w,h)
# sample center region colors
for pos in [(320,240),(320,200),(320,300),(200,200),(400,200)]:
    print(pos, im.getpixel(pos))
# threshold bright (gray > 180) and find connected components using BFS
# create binary where r,g,b all >150 and low saturation?
pix=im.load()
bin=[[0]*w for _ in range(h)]
for y in range(h):
    for x in range(w):
        r,g,b=pix[x,y]
        if r>120 and g>120 and b>120:
            bin[y][x]=1
# BFS components
seen=[[False]*w for _ in range(h)]
comps=[]
for y in range(h):
    for x in range(w):
        if bin[y][x] and not seen[y][x]:
            stack=[(x,y)]; seen[y][x]=True; xs=[]; ys=[]
            while stack:
                cx,cy=stack.pop(); xs.append(cx); ys.append(cy)
                for nx,ny in ((cx+1,cy),(cx-1,cy),(cx,cy+1),(cx,cy-1)):
